18	//       index 为 1D 共享，每个 index 值选择一整行 innerSize 个元素
19	//       动态核分配: taskId 交错分配 outerIdx + indexRange
20	//       UB 级 Tiling: 小尾轴(≤4096)多行批量 / 大尾轴分块
21	// ============================================================
22	
23	#include "kernel_operator.h"
24	
25	using namespace AscendC;
26	
27	constexpr int64_t UB_CAPACITY = 192 * 1024;
28	constexpr int64_t MAX_CORES = 40;
29	constexpr int64_t MAX_INDEX_BATCH = 512;
30	constexpr int64_t SMALL_INNER_THRESHOLD = 4096;
31	constexpr int64_t BUFFER_NUM = 2;
32	
33	template <typename T>
34	class <OpName>Kernel {
35	public:
36	    __aicore__ inline <OpName>Kernel() {}
37	
38	    __aicore__ inline void Init(GM_ADDR input, GM_ADDR index, GM_ADDR output,
39	                                int64_t outerSize, int64_t innerSize,
40	                                int64_t indexSize, int64_t srcDimSize,
41	                                int64_t totalLength, int64_t coresPerOuter);
42	    __aicore__ inline void Process();
43	
44	private:
45	    __aicore__ inline void ProcessIndexRange(int64_t outerIdx,
46	                                              int64_t indexStart, int64_t indexEnd);
47	    __aicore__ inline void ProcessSmallInner(int64_t outerIdx,
48	                                              int64_t indexStart, int64_t indexEnd);
49	    __aicore__ inline void ProcessLargeInner(int64_t outerIdx,
50	                                              int64_t indexStart, int64_t indexEnd);
51	    __aicore__ inline void LoadIndexBatch(int64_t batchStart, int64_t batchSize);
52	    __aicore__ inline int32_t GetIndexValue(int64_t localIdx);
53	
54	private:
55	    TPipe pipe;
56	    TBuf<TPosition::VECCALC> indexBuf;                // 共享索引缓冲
57	    TQue<TPosition::VECOUT, BUFFER_NUM> outQueue;      // 双缓冲输出
58	
59	    GlobalTensor<T> inputGm;
60	    GlobalTensor<int32_t> indexGm;
61	    GlobalTensor<T> outputGm;
62	
63	    // 3D 维度
64	    int64_t outerSize_ = 0;
65	    int64_t innerSize_ = 0;
66	    int64_t indexSize_ = 0;
67	    int64_t srcDimSize_ = 0;
68	    int64_t coresPerOuter_ = 0;
69	    int64_t totalLength_ = 0;
70	
71	    // UB 级 Tiling 派生参数
72	    int64_t alignedInnerSize_ = 0;
73	    int64_t indexBatchSize_ = 0;
74	    int64_t tileSize_ = 0;
75	    int64_t alignedTileSize_ = 0;
76	    int64_t tileCount_ = 0;
77	    int64_t batchRows_ = 1;
78	    bool isSmallInner_ = false;
79	};
80	
81	// =========================== Init start ============================
82	
83	template <typename T>
84	__aicore__ inline void <OpName>Kernel<T>::Init(GM_ADDR input, GM_ADDR index, GM_ADDR output,
85	                                                int64_t outerSize, int64_t innerSize,
86	                                                int64_t indexSize, int64_t srcDimSize,
87	                                                int64_t totalLength, int64_t coresPerOuter) {
88	    outerSize_ = outerSize;
89	    innerSize_ = innerSize;
90	    indexSize_ = indexSize;
91	    srcDimSize_ = srcDimSize;
92	    totalLength_ = totalLength;
93	    coresPerOuter_ = coresPerOuter;
94	
95	    inputGm.SetGlobalBuffer((__gm__ T*)input, totalLength);
96	    indexGm.SetGlobalBuffer((__gm__ int32_t*)index);
97	    outputGm.SetGlobalBuffer((__gm__ T*)output);
98	
99	    // 对齐 innerSize（32 字节对齐）
100	    constexpr int64_t alignNum = 32 / sizeof(T);  // float32:8, float16/bf16:16
101	    alignedInnerSize_ = (innerSize_ + alignNum - 1) / alignNum * alignNum;
102	    if (alignedInnerSize_ == 0) alignedInnerSize_ = alignNum;
103	
104	    // 索引批次
105	    indexBatchSize_ = indexSize_ < MAX_INDEX_BATCH ? indexSize_ : MAX_INDEX_BATCH;
106	
107	    // 索引缓冲区大小（32 字节对齐）
108	    int64_t indexAlignedSize = (indexBatchSize_ * sizeof(int32_t) + 31) / 32 * 32;
109	    pipe.InitBuffer(indexBuf, indexAlignedSize);
110	
111	    // 可用 UB 空间（减去 indexBuf）
112	    int64_t availableUB = UB_CAPACITY - indexAlignedSize;
113	    int64_t maxElementsInUB = availableUB / sizeof(T) / BUFFER_NUM;
114	
115	    // 小尾轴 / 大尾轴判断
116	    isSmallInner_ = (innerSize_ <= SMALL_INNER_THRESHOLD);
117	
118	    if (isSmallInner_) {
119	        // 小尾轴: 多行批量处理
120	        int64_t maxRows = maxElementsInUB / alignedInnerSize_;
121	        batchRows_ = maxRows < indexBatchSize_ ? maxRows : indexBatchSize_;
122	        if (batchRows_ < 1) batchRows_ = 1;
123	
124	        tileSize_ = innerSize_;
125	        alignedTileSize_ = alignedInnerSize_;
126	        tileCount_ = 1;
127	    } else {
128	        // 大尾轴: 分块处理
129	        if (alignedInnerSize_ > maxElementsInUB) {
130	            tileSize_ = maxElementsInUB / alignNum * alignNum;
131	            alignedTileSize_ = tileSize_;
132	            tileCount_ = (innerSize_ + tileSize_ - 1) / tileSize_;
133	        } else {
134	            tileSize_ = innerSize_;
135	            alignedTileSize_ = alignedInnerSize_;
136	            tileCount_ = 1;
137	        }
138	        batchRows_ = 1;
139	    }
140	
141	    pipe.InitBuffer(outQueue, BUFFER_NUM, alignedTileSize_ * sizeof(T) * batchRows_);
142	}
143	
144	// =========================== Init end ============================
145	
146	
147	// =========================== 索引加载 start ============================
148	
149	template <typename T>
150	__aicore__ inline void <OpName>Kernel<T>::LoadIndexBatch(int64_t batchStart, int64_t batchSize) {
151	    LocalTensor<int32_t> indexLocal = indexBuf.Get<int32_t>();
152	
153	    DataCopyExtParams copyParams;
154	    copyParams.blockCount = 1;
155	    copyParams.blockLen = static_cast<uint32_t>(batchSize * sizeof(int32_t));
156	    copyParams.srcStride = 0;
157	    copyParams.dstStride = 0;
158	
159	    DataCopyPadExtParams<int32_t> padParams;
160	    padParams.isPad = false;
161	
162	    DataCopyPad(indexLocal, indexGm[batchStart], copyParams, padParams);
163	    PipeBarrier<PIPE_ALL>();
164	}
165	
166	template <typename T>
167	__aicore__ inline int32_t <OpName>Kernel<T>::GetIndexValue(int64_t localIdx) {
168	    LocalTensor<int32_t> indexLocal = indexBuf.Get<int32_t>();
169	    return indexLocal.GetValue(localIdx);
170	}
171	
172	// =========================== 索引加载 end ============================
173	
174	
175	// =========================== 小尾轴处理 start ============================
176	// innerSize ≤ 4096: 多行批量，indexBuf 分批加载，每批 batchRows_ 行
177	
178	template <typename T>
179	__aicore__ inline void <OpName>Kernel<T>::ProcessSmallInner(int64_t outerIdx,
180	                                                              int64_t indexStart,
181	                                                              int64_t indexEnd) {
182	    int64_t idxProcessed = indexStart;
183	    while (idxProcessed < indexEnd) {
184	        int64_t currentBatch = indexEnd - idxProcessed;
185	        if (currentBatch > batchRows_) currentBatch = batchRows_;
186	
187	        // 加载一批索引
188	        LoadIndexBatch(idxProcessed, currentBatch);
189	
190	        // 逐行处理: 每个 index 拷贝 innerSize 个连续元素
191	        for (int64_t i = 0; i < currentBatch; i++) {
192	            int32_t indexValue = GetIndexValue(i);
193	            int64_t inputOffset = outerIdx * srcDimSize_ * innerSize_
194	                                  + indexValue * innerSize_;
195	            int64_t outputOffset = outerIdx * indexSize_ * innerSize_
196	                                   + (idxProcessed + i) * innerSize_;
197	
198	            LocalTensor<T> outputLocal = outQueue.AllocTensor<T>();
199	
200	            DataCopyExtParams copyParams;
201	            copyParams.blockCount = 1;
202	            copyParams.blockLen = static_cast<uint32_t>(innerSize_ * sizeof(T));
203	            copyParams.srcStride = 0;
204	            copyParams.dstStride = 0;
205	            DataCopyPadExtParams<T> padParams;
206	            padParams.isPad = false;
207	
208	            DataCopyPad(outputLocal, inputGm[inputOffset], copyParams, padParams);
209	            PipeBarrier<PIPE_ALL>();
210	
211	            outQueue.EnQue<T>(outputLocal);
212	
213	            LocalTensor<T> outLocal = outQueue.DeQue<T>();
214	            DataCopyPad(outputGm[outputOffset], outLocal, copyParams);
215	            outQueue.FreeTensor(outLocal);
216	        }
217	
218	        idxProcessed += currentBatch;
219	    }
220	}
221	
222	// =========================== 小尾轴处理 end ============================
223	
224	
225	// =========================== 大尾轴处理 start ============================
226	// innerSize > 4096: 分块处理，沿 innerSize 切分为 tileSize_ 大小的块
227	
228	template <typename T>
229	__aicore__ inline void <OpName>Kernel<T>::ProcessLargeInner(int64_t outerIdx,
230	                                                              int64_t indexStart,
231	                                                              int64_t indexEnd) {
232	    // 加载本批索引
233	    int64_t currentBatch = indexEnd - indexStart;
234	    if (currentBatch > indexBatchSize_) currentBatch = indexBatchSize_;
235	    LoadIndexBatch(indexStart, currentBatch);
236	
237	    for (int64_t i = 0; i < currentBatch; i++) {
238	        int32_t indexValue = GetIndexValue(i);
239	        int64_t inputBase = outerIdx * srcDimSize_ * innerSize_
240	                            + indexValue * innerSize_;
241	        int64_t outputBase = outerIdx * indexSize_ * innerSize_
242	                             + (indexStart + i) * innerSize_;
243	
244	        // 沿 innerSize 分块
245	        for (int64_t t = 0; t < tileCount_; t++) {
246	            int64_t tileStart = t * tileSize_;
247	            int64_t curTileSize = tileSize_;
248	            if (tileStart + curTileSize > innerSize_) {
249	                curTileSize = innerSize_ - tileStart;
250	            }
251	
252	            LocalTensor<T> outputLocal = outQueue.AllocTensor<T>();
253	
254	            DataCopyExtParams copyParams;
255	            copyParams.blockCount = 1;
256	            copyParams.blockLen = static_cast<uint32_t>(curTileSize * sizeof(T));
257	            copyParams.srcStride = 0;
258	            copyParams.dstStride = 0;
259	            DataCopyPadExtParams<T> padParams;
260	            padParams.isPad = false;
261	
262	            DataCopyPad(outputLocal, inputGm[inputBase + tileStart], copyParams, padParams);
263	            PipeBarrier<PIPE_ALL>();
264	
265	            outQueue.EnQue<T>(outputLocal);
266	
267	            LocalTensor<T> outLocal = outQueue.DeQue<T>();
268	            DataCopyPad(outputGm[outputBase + tileStart], outLocal, copyParams);
269	            outQueue.FreeTensor(outLocal);
270	        }
271	    }
272	}
273	
274	// =========================== 大尾轴处理 end ============================
275	
276	
277	// =========================== ProcessIndexRange start ============================
278	
279	template <typename T>
280	__aicore__ inline void <OpName>Kernel<T>::ProcessIndexRange(int64_t outerIdx,
281	                                                              int64_t indexStart,
282	                                                              int64_t indexEnd) {
283	    if (isSmallInner_) {
284	        ProcessSmallInner(outerIdx, indexStart, indexEnd);
285	    } else {
286	        ProcessLargeInner(outerIdx, indexStart, indexEnd);
287	    }
288	}
289	
290	// =========================== ProcessIndexRange end ============================
291	
292	
293	// =========================== Process 主入口 start ============================
294	
295	template <typename T>
296	__aicore__ inline void <OpName>Kernel<T>::Process() {
297	    int64_t blockIdx = GetBlockIdx();
298	    int64_t totalTasks = outerSize_ * coresPerOuter_;
299	    int64_t usedCores = totalTasks < MAX_CORES ? totalTasks : MAX_CORES;
300	
301	    if (blockIdx >= usedCores) return;
302	
303	    int64_t indexPerCore = (indexSize_ + coresPerOuter_ - 1) / coresPerOuter_;
304	
305	    // 核 0 处理任务 0, usedCores, 2*usedCores...
306	    // 核 1 处理任务 1, usedCores+1, 2*usedCores+1...
307	    for (int64_t taskId = blockIdx; taskId < totalTasks; taskId += usedCores) {
308	        int64_t outerIdx = taskId / coresPerOuter_;
309	        int64_t subIdx = taskId % coresPerOuter_;
310	
311	        int64_t indexStart = subIdx * indexPerCore;
312	        int64_t indexEnd = indexStart + indexPerCore;
313	        if (indexEnd > indexSize_) indexEnd = indexSize_;
314	
315	        if (indexStart >= indexSize_) continue;
316	
317	        ProcessIndexRange(outerIdx, indexStart, indexEnd);
318	    }
319	}
320	
321	// =========================== Process 主入口 end ============================
322	
323	
324	// =========================== Kernel 入口 start ============================
325	// 搬运类算子不做数值计算，bf16 与 fp16 均为 2 字节，统一走 half 路径搬运
326	
327	extern "C" __global__ __aicore__ void <op_name>(GM_ADDR input, GM_ADDR index, GM_ADDR output,
328	                                                  int64_t outerSize, int64_t innerSize,
329	                                                  int64_t indexSize, int64_t srcDimSize,
330	                                                  int64_t totalLength, int64_t coresPerOuter) {
331	    if (outerSize * srcDimSize * innerSize > 0) {
332	        <OpName>Kernel<float> op;
333	        op.Init(input, index, output, outerSize, innerSize,
334	                indexSize, srcDimSize, totalLength, coresPerOuter);
335	        op.Process();
336	    }
337	}
338	
339	// =========================== Kernel 入口 end ============================
340

