13	#include "kernel_operator.h"
14	
15	using namespace AscendC;
16	
17	constexpr int64_t UB_CAPACITY = 192 * 1024;
18	constexpr int64_t MAX_CORES = 40;
19	constexpr int64_t MAX_INDEX_BATCH = 512;
20	constexpr int64_t SMALL_INNER_THRESHOLD = 4096;
21	constexpr int64_t BUFFER_NUM = 2;
22	
23	template <typename T>
24	class IndexKernel {
25	public:
26	    __aicore__ inline IndexKernel() {}
27	
28	    __aicore__ inline void Init(GM_ADDR input, GM_ADDR index, GM_ADDR output,
29	                                int64_t outerSize, int64_t innerSize,
30	                                int64_t indexSize, int64_t srcDimSize,
31	                                int64_t inputLength, int64_t totalLength,
32	                                int64_t coresPerOuter);
33	    __aicore__ inline void Process();
34	
35	private:
36	    __aicore__ inline void ProcessIndexRange(int64_t outerIdx,
37	                                              int64_t indexStart, int64_t indexEnd);
38	    __aicore__ inline void ProcessSmallInner(int64_t outerIdx,
39	                                              int64_t indexStart, int64_t indexEnd);
40	    __aicore__ inline void ProcessLargeInner(int64_t outerIdx,
41	                                              int64_t indexStart, int64_t indexEnd);
42	    __aicore__ inline void LoadIndexBatch(int64_t batchStart, int64_t batchSize);
43	    __aicore__ inline int32_t GetIndexValue(int64_t localIdx);
44	
45	private:
46	    TPipe pipe;
47	    TBuf<TPosition::VECCALC> indexBuf;                // 共享索引缓冲
48	    TQue<TPosition::VECOUT, BUFFER_NUM> outQueue;      // 双缓冲输出
49	
50	    GlobalTensor<T> inputGm;
51	    GlobalTensor<int32_t> indexGm;
52	    GlobalTensor<T> outputGm;
53	
54	    // 3D 维度
55	    int64_t outerSize_ = 0;
56	    int64_t innerSize_ = 0;
57	    int64_t indexSize_ = 0;
58	    int64_t srcDimSize_ = 0;
59	    int64_t coresPerOuter_ = 0;
60	    int64_t totalLength_ = 0;
61	
62	    // UB 级 Tiling 派生参数
63	    int64_t alignedInnerSize_ = 0;
64	    int64_t indexBatchSize_ = 0;
65	    int64_t tileSize_ = 0;
66	    int64_t alignedTileSize_ = 0;
67	    int64_t tileCount_ = 0;
68	    int64_t batchRows_ = 1;
69	    bool isSmallInner_ = false;
70	};
71	
72	// =========================== Init start ============================
73	
74	template <typename T>
75	__aicore__ inline void IndexKernel<T>::Init(GM_ADDR input, GM_ADDR index, GM_ADDR output,
76	                                             int64_t outerSize, int64_t innerSize,
77	                                             int64_t indexSize, int64_t srcDimSize,
78	                                             int64_t inputLength, int64_t totalLength,
79	                                             int64_t coresPerOuter) {
80	    outerSize_ = outerSize;
81	    innerSize_ = innerSize;
82	    indexSize_ = indexSize;
83	    srcDimSize_ = srcDimSize;
84	    totalLength_ = totalLength;
85	    coresPerOuter_ = coresPerOuter;
86	
87	    inputGm.SetGlobalBuffer((__gm__ T*)input, inputLength);
88	    indexGm.SetGlobalBuffer((__gm__ int32_t*)index);
89	    outputGm.SetGlobalBuffer((__gm__ T*)output);
90	
91	    // 对齐 innerSize（32 字节对齐）
92	    constexpr int64_t alignNum = 32 / sizeof(T);  // float32:8, float16/bf16:16
93	    alignedInnerSize_ = (innerSize_ + alignNum - 1) / alignNum * alignNum;
94	    if (alignedInnerSize_ == 0) alignedInnerSize_ = alignNum;
95	
96	    // 索引批次
97	    indexBatchSize_ = indexSize_ < MAX_INDEX_BATCH ? indexSize_ : MAX_INDEX_BATCH;
98	
99	    // 索引缓冲区大小（32 字节对齐）
100	    int64_t indexAlignedSize = (indexBatchSize_ * sizeof(int32_t) + 31) / 32 * 32;
101	    pipe.InitBuffer(indexBuf, indexAlignedSize);
102	
103	    // 可用 UB 空间（减去 indexBuf）
104	    int64_t availableUB = UB_CAPACITY - indexAlignedSize;
105	    int64_t maxElementsInUB = availableUB / sizeof(T) / BUFFER_NUM;
106	
107	    // 小尾轴 / 大尾轴判断
108	    isSmallInner_ = (innerSize_ <= SMALL_INNER_THRESHOLD);
109	
110	    if (isSmallInner_) {
111	        // 小尾轴: 多行批量处理
112	        int64_t maxRows = maxElementsInUB / alignedInnerSize_;
113	        batchRows_ = maxRows < indexBatchSize_ ? maxRows : indexBatchSize_;
114	        if (batchRows_ < 1) batchRows_ = 1;
115	
116	        tileSize_ = innerSize_;
117	        alignedTileSize_ = alignedInnerSize_;
118	        tileCount_ = 1;
119	    } else {
120	        // 大尾轴: 分块处理
121	        if (alignedInnerSize_ > maxElementsInUB) {
122	            tileSize_ = maxElementsInUB / alignNum * alignNum;
123	            alignedTileSize_ = tileSize_;
124	            tileCount_ = (innerSize_ + tileSize_ - 1) / tileSize_;
125	        } else {
126	            tileSize_ = innerSize_;
127	            alignedTileSize_ = alignedInnerSize_;
128	            tileCount_ = 1;
129	        }
130	        batchRows_ = 1;
131	    }
132	
133	    pipe.InitBuffer(outQueue, BUFFER_NUM, alignedTileSize_ * sizeof(T) * batchRows_);
134	}
135	
136	// =========================== Init end ============================
137	
138	
139	// =========================== 索引加载 start ============================
140	
141	template <typename T>
142	__aicore__ inline void IndexKernel<T>::LoadIndexBatch(int64_t batchStart, int64_t batchSize) {
143	    LocalTensor<int32_t> indexLocal = indexBuf.Get<int32_t>();
144	
145	    DataCopyExtParams copyParams;
146	    copyParams.blockCount = 1;
147	    copyParams.blockLen = static_cast<uint32_t>(batchSize * sizeof(int32_t));
148	    copyParams.srcStride = 0;
149	    copyParams.dstStride = 0;
150	
151	    DataCopyPadExtParams<int32_t> padParams;
152	    padParams.isPad = false;
153	
154	    DataCopyPad(indexLocal, indexGm[batchStart], copyParams, padParams);
155	    PipeBarrier<PIPE_ALL>();
156	}
157	
158	template <typename T>
159	__aicore__ inline int32_t IndexKernel<T>::GetIndexValue(int64_t localIdx) {
160	    LocalTensor<int32_t> indexLocal = indexBuf.Get<int32_t>();
161	    return indexLocal.GetValue(localIdx);
162	}
163	
164	// =========================== 索引加载 end ============================
165	
166	
167	// =========================== 小尾轴处理 start ============================
168	// innerSize ≤ 4096: 多行批量，indexBuf 分批加载，每批 batchRows_ 行
169	
170	template <typename T>
171	__aicore__ inline void IndexKernel<T>::ProcessSmallInner(int64_t outerIdx,
172	                                                          int64_t indexStart,
173	                                                          int64_t indexEnd) {
174	    int64_t idxProcessed = indexStart;
175	    while (idxProcessed < indexEnd) {
176	        int64_t currentBatch = indexEnd - idxProcessed;
177	        if (currentBatch > batchRows_) currentBatch = batchRows_;
178	
179	        // 加载一批索引
180	        LoadIndexBatch(idxProcessed, currentBatch);
181	
182	        // 逐行处理: 每个 index 拷贝 innerSize 个连续元素
183	        for (int64_t i = 0; i < currentBatch; i++) {
184	            int32_t indexValue = GetIndexValue(i);
185	            int64_t inputOffset = outerIdx * srcDimSize_ * innerSize_
186	                                  + indexValue * innerSize_;
187	            int64_t outputOffset = outerIdx * indexSize_ * innerSize_
188	                                   + (idxProcessed + i) * innerSize_;
189	
190	            LocalTensor<T> outputLocal = outQueue.AllocTensor<T>();
191	
192	            DataCopyExtParams copyParams;
193	            copyParams.blockCount = 1;
194	            copyParams.blockLen = static_cast<uint32_t>(innerSize_ * sizeof(T));
195	            copyParams.srcStride = 0;
196	            copyParams.dstStride = 0;
197	            DataCopyPadExtParams<T> padParams;
198	            padParams.isPad = false;
199	
200	            DataCopyPad(outputLocal, inputGm[inputOffset], copyParams, padParams);
201	            PipeBarrier<PIPE_ALL>();
202	
203	            outQueue.EnQue<T>(outputLocal);
204	
205	            LocalTensor<T> outLocal = outQueue.DeQue<T>();
206	            DataCopyPad(outputGm[outputOffset], outLocal, copyParams);
207	            outQueue.FreeTensor(outLocal);
208	        }
209	
210	        idxProcessed += currentBatch;
211	    }
212	}
213	
214	// =========================== 小尾轴处理 end ============================
215	
216	
217	// =========================== 大尾轴处理 start ============================
218	// innerSize > 4096: 分块处理，沿 innerSize 切分为 tileSize_ 大小的块
219	
220	template <typename T>
221	__aicore__ inline void IndexKernel<T>::ProcessLargeInner(int64_t outerIdx,
222	                                                          int64_t indexStart,
223	                                                          int64_t indexEnd) {
224	    // 加载本批索引
225	    int64_t currentBatch = indexEnd - indexStart;
226	    if (currentBatch > indexBatchSize_) currentBatch = indexBatchSize_;
227	    LoadIndexBatch(indexStart, currentBatch);
228	
229	    for (int64_t i = 0; i < currentBatch; i++) {
230	        int32_t indexValue = GetIndexValue(i);
231	        int64_t inputBase = outerIdx * srcDimSize_ * innerSize_
232	                            + indexValue * innerSize_;
233	        int64_t outputBase = outerIdx * indexSize_ * innerSize_
234	                             + (indexStart + i) * innerSize_;
235	
236	        // 沿 innerSize 分块
237	        for (int64_t t = 0; t < tileCount_; t++) {
238	            int64_t tileStart = t * tileSize_;
239	            int64_t curTileSize = tileSize_;
240	            if (tileStart + curTileSize > innerSize_) {
241	                curTileSize = innerSize_ - tileStart;
242	            }
243	
244	            LocalTensor<T> outputLocal = outQueue.AllocTensor<T>();
245	
246	            DataCopyExtParams copyParams;
247	            copyParams.blockCount = 1;
248	            copyParams.blockLen = static_cast<uint32_t>(curTileSize * sizeof(T));
249	            copyParams.srcStride = 0;
250	            copyParams.dstStride = 0;
251	            DataCopyPadExtParams<T> padParams;
252	            padParams.isPad = false;
253	
254	            DataCopyPad(outputLocal, inputGm[inputBase + tileStart], copyParams, padParams);
255	            PipeBarrier<PIPE_ALL>();
256	
257	            outQueue.EnQue<T>(outputLocal);
258	
259	            LocalTensor<T> outLocal = outQueue.DeQue<T>();
260	            DataCopyPad(outputGm[outputBase + tileStart], outLocal, copyParams);
261	            outQueue.FreeTensor(outLocal);
262	        }
263	    }
264	}
265	
266	// =========================== 大尾轴处理 end ============================
267	
268	
269	// =========================== ProcessIndexRange start ============================
270	
271	template <typename T>
272	__aicore__ inline void IndexKernel<T>::ProcessIndexRange(int64_t outerIdx,
273	                                                          int64_t indexStart,
274	                                                          int64_t indexEnd) {
275	    if (isSmallInner_) {
276	        ProcessSmallInner(outerIdx, indexStart, indexEnd);
277	    } else {
278	        ProcessLargeInner(outerIdx, indexStart, indexEnd);
279	    }
280	}
281	
282	// =========================== ProcessIndexRange end ============================
283	
284	
285	// =========================== Process 主入口 start ============================
286	
287	template <typename T>
288	__aicore__ inline void IndexKernel<T>::Process() {
289	    int64_t blockIdx = GetBlockIdx();
290	    int64_t totalTasks = outerSize_ * coresPerOuter_;
291	    int64_t usedCores = totalTasks < MAX_CORES ? totalTasks : MAX_CORES;
292	
293	    if (blockIdx >= usedCores) return;
294	
295	    int64_t indexPerCore = (indexSize_ + coresPerOuter_ - 1) / coresPerOuter_;
296	
297	    // 核 0 处理任务 0, usedCores, 2*usedCores...
298	    // 核 1 处理任务 1, usedCores+1, 2*usedCores+1...
299	    for (int64_t taskId = blockIdx; taskId < totalTasks; taskId += usedCores) {
300	        int64_t outerIdx = taskId / coresPerOuter_;
301	        int64_t subIdx = taskId % coresPerOuter_;
302	
303	        int64_t indexStart = subIdx * indexPerCore;
304	        int64_t indexEnd = indexStart + indexPerCore;
305	        if (indexEnd > indexSize_) indexEnd = indexSize_;
306	
307	        if (indexStart >= indexSize_) continue;
308	
309	        ProcessIndexRange(outerIdx, indexStart, indexEnd);
310	    }
311	}
312	
313	// =========================== Process 主入口 end ============================
314	
315	
316	// =========================== Kernel 入口 start ============================
317	// 搬运类算子不做数值计算，bf16 与 fp16 均为 2 字节，统一走 half 路径搬运
318	
319	extern "C" __global__ __aicore__ void index(GM_ADDR input, GM_ADDR index, GM_ADDR output,
320	                                             int64_t outerSize, int64_t innerSize,
321	                                             int64_t indexSize, int64_t srcDimSize,
322	                                             int64_t totalLength, int64_t coresPerOuter) {
323	    if (outerSize * srcDimSize * innerSize > 0) {
324	        IndexKernel<float> op;
325	        op.Init(input, index, output, outerSize, innerSize,
326	                indexSize, srcDimSize, totalLength, coresPerOuter);
327	        op.Process();
328	    }
329	}
330	
331	// =========================== Kernel 入口 end ============================
332

